page_settings.custom_css:
body{background:#F6F6F6}
.rt-obg{background:#FFFFFF;border-radius:14px;box-shadow:0 10px 40px rgba(0,0,0,.07);padding:56px 56px 44px;text-align:center}
@media (max-width:767px){.rt-obg{padding:40px 22px 32px}}
.rt-obg .eyebrow{font-family:Roboto,sans-serif;font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;color:#C56F00;margin:0}
.rt-obg h1{font-family:Montserrat,sans-serif;font-weight:400;font-size:clamp(30px,4.4vw,46px);line-height:1.12;color:#3C3D3D;margin:16px auto 16px;max-width:640px}
.rt-obg-lead{font-size:17px;line-height:1.65;color:#666;max-width:560px;margin:0 auto}
.rt-obg-ok{width:84px;height:84px;margin:0 auto 22px}
.rt-obg-ok svg{width:100%;height:100%}
.rt-obg-c{stroke:#E98300;stroke-width:3;stroke-dasharray:151;stroke-dashoffset:151;animation:rt-obg-c .7s cubic-bezier(.65,0,.45,1) forwards}
.rt-obg-v{stroke:#E98300;stroke-width:4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:36;stroke-dashoffset:36;animation:rt-obg-c .4s .6s cubic-bezier(.65,0,.45,1) forwards}
@keyframes rt-obg-c{to{stroke-dashoffset:0}}
.rt-obg-passos,.rt-obg-insp{margin:40px 0 0;padding-top:34px;border-top:1px solid #EEE}
.rt-obg-passos ol{list-style:none;margin:22px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:22px;text-align:left}
@media (max-width:767px){.rt-obg-passos ol{grid-template-columns:1fr}}
.rt-obg-passos li{display:flex;gap:14px;align-items:flex-start}
.rt-obg-passos li span{flex:0 0 34px;height:34px;border-radius:50%;background:#FFF1E0;color:#E98300;font-family:Montserrat,sans-serif;font-weight:700;display:flex;align-items:center;justify-content:center}
.rt-obg-passos strong{display:block;font-family:Montserrat,sans-serif;font-size:15px;color:#3C3D3D;margin-bottom:4px}
.rt-obg-passos p{margin:0;font-size:14px;line-height:1.5;color:#777}
.rt-obg-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px;text-align:left}
@media (max-width:767px){.rt-obg-cards{grid-template-columns:1fr}}
.rt-obg-card{position:relative;display:flex;flex-direction:column;gap:6px;background:#FAFAFA;border-radius:10px;padding:22px 20px;color:#3C3D3D;text-decoration:none;overflow:hidden;transition:transform .4s cubic-bezier(.22,.61,.36,1),box-shadow .4s}
.rt-obg-card::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;background:#E98300;transform:scaleX(0);transform-origin:0 50%;transition:transform .5s cubic-bezier(.22,.61,.36,1)}
.rt-obg-card:hover{transform:translateY(-4px);box-shadow:0 14px 34px rgba(0,0,0,.1);color:#3C3D3D}
.rt-obg-card:hover::before{transform:scaleX(1)}
.rt-obg-card strong{font-family:Montserrat,sans-serif;font-size:17px}
.rt-obg-card span{font-size:14px;color:#777;line-height:1.5}
.rt-obg-card em{font-style:normal;margin-top:6px;font-size:12px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:#C56F00}
.rt-obg-btns{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:38px}
.rt-obg-btn{display:inline-flex;align-items:center;gap:10px;padding:15px 28px;border-radius:8px;border:1px solid #D9D9D9;background:#FFFFFF;color:#3C3D3D;font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;text-decoration:none;transition:background .25s,color .25s,border-color .25s,transform .25s}
.rt-obg-btn:hover{border-color:#E98300;color:#E98300;transform:translateY(-2px)}
.rt-obg-btn svg{width:20px;height:20px}
.rt-obg-btn--zap{background:#25D366;border-color:#25D366;color:#FFFFFF}
.rt-obg-btn--zap:hover{background:#1DA851;border-color:#1DA851;color:#FFFFFF}
.rt-obg-redes{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:30px;font-size:13px;color:#8A8A8A}
.rt-obg-redes span{margin-right:6px}
.rt-obg-redes a{width:38px;height:38px;border-radius:50%;background:#FFF1E0;color:#E98300;display:flex;align-items:center;justify-content:center;transition:background .25s,color .25s}
.rt-obg-redes a:hover{background:#E98300;color:#FFFFFF}
.rt-obg-redes svg{width:18px;height:18px}
.elementor-widget-html:has(.rt-obg){width:100%}
/* newsletter */
.rt-obg-news{padding-bottom:80px!important}
@media (max-width:767px){.rt-obg-news{padding-bottom:56px!important}}
.rt-obg-news>.e-con-inner{background:#3C3D3D;border-radius:14px;padding:40px 48px!important;gap:18px}
@media (max-width:767px){.rt-obg-news>.e-con-inner{padding:30px 22px!important}}
.rt-obg-news-in{text-align:center}
.rt-obg-news-in .eyebrow{font-family:Roboto,sans-serif;font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;color:#FFB700;margin:0}
.rt-obg-news-in h2{font-family:Montserrat,sans-serif;font-weight:400;font-size:28px;color:#FFFFFF;margin:10px 0 6px}
.rt-obg-news-in p:last-child{color:#CFCFCF;margin:0}
.rt-obg-news .elementor-widget-html,.rt-obg-news .elementor-widget-jet-form-builder-form{width:100%}
.rt-obg-news .wp-block-columns{display:flex;flex-wrap:wrap;gap:12px;margin:0;align-items:flex-start}
.rt-obg-news .wp-block-column{flex:1 1 200px!important;margin:0!important}
.rt-obg-news .wp-block-column:last-child{flex:0 0 auto!important}
.rt-obg-news .jet-form-builder-row{margin:0}
.rt-obg-news .jet-form-builder__label{display:none}
.rt-obg-news .jet-form-builder__field.text-field{width:100%;min-height:52px;padding:12px 16px;border:0;border-radius:8px;background:#FFFFFF;font-size:15px;color:#3C3D3D}
.rt-obg-news .jet-form-builder__action-button{min-height:52px;padding:12px 34px;border:0;border-radius:8px;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-size:14px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:background .25s}
.rt-obg-news .jet-form-builder__action-button:hover{background:#FFB700;color:#000}
.rt-obg-news .jet-form-builder-messages-wrap{color:#FFFFFF}
.rt-obg-news p:empty{display:none}
@media (max-width:767px){.rt-obg-news .wp-block-column:last-child{flex:1 1 100%!important}.rt-obg-news .jet-form-builder__action-button{width:100%}}
.page .entry-title,.page-header{display:none}
